CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, subject TEXT UNIQUE NOT NULL, phone TEXT UNIQUE, email TEXT, role TEXT NOT NULL DEFAULT 'user', status TEXT NOT NULL DEFAULT 'active', created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS preferences (user_id TEXT PRIMARY KEY REFERENCES users(id), privacy TEXT NOT NULL DEFAULT '{}', notifications TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT UNIQUE NOT NULL, refresh_hash TEXT UNIQUE NOT NULL, family_id TEXT NOT NULL, expires_at BIGINT NOT NULL, refresh_expires_at BIGINT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_challenges (id TEXT PRIMARY KEY, identity TEXT NOT NULL, user_id TEXT REFERENCES users(id), code_hash TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, consumed INTEGER NOT NULL DEFAULT 0, expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, resets_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS commands (user_id TEXT NOT NULL REFERENCES users(id), operation TEXT NOT NULL, request_key TEXT NOT NULL, request_hash TEXT NOT NULL, response TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(user_id, request_key));
CREATE TABLE IF NOT EXISTS wallet_entries (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, amount INTEGER NOT NULL, locked_delta INTEGER NOT NULL DEFAULT 0, ref TEXT NOT NULL, dedupe TEXT UNIQUE NOT NULL, description TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS wallet_user ON wallet_entries(user_id,created_at);
CREATE TABLE IF NOT EXISTS holds (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), scope TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>=0), status TEXT NOT NULL, UNIQUE(user_id,scope));
CREATE TABLE IF NOT EXISTS rewards (user_id TEXT NOT NULL REFERENCES users(id), reward_key TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(user_id,reward_key));
CREATE TABLE IF NOT EXISTS store_transactions (transaction_id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL, platform TEXT NOT NULL, status TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (user_id TEXT PRIMARY KEY REFERENCES users(id), product_id TEXT NOT NULL, original_transaction TEXT UNIQUE NOT NULL, status TEXT NOT NULL, expires_at BIGINT NOT NULL, anchor_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_events (id TEXT PRIMARY KEY, payload_hash TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, host_id TEXT NOT NULL REFERENCES users(id), sport TEXT NOT NULL, status TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>=2), starts_at BIGINT NOT NULL, ends_at BIGINT NOT NULL, commitment INTEGER NOT NULL CHECK(commitment>=0), city TEXT NOT NULL, district TEXT NOT NULL, latitude REAL, longitude REAL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS events_discovery ON events(status,city,sport,starts_at);
CREATE TABLE IF NOT EXISTS event_members (event_id TEXT NOT NULL REFERENCES events(id), user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, side TEXT, checked_in_at BIGINT, joined_at BIGINT NOT NULL, PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS join_requests (id TEXT PRIMARY KEY, scope TEXT NOT NULL, scope_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, payload TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(scope,scope_id,user_id));
CREATE TABLE IF NOT EXISTS waitlist (event_id TEXT NOT NULL REFERENCES events(id), user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, offered_until BIGINT, created_at BIGINT NOT NULL, PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS results (event_id TEXT PRIMARY KEY REFERENCES events(id), submitted_by TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL, status TEXT NOT NULL, dispute_until BIGINT NOT NULL, finalized_at BIGINT, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS result_confirmations (event_id TEXT NOT NULL REFERENCES results(event_id), user_id TEXT NOT NULL REFERENCES users(id), created_at BIGINT NOT NULL, PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS feedback (event_id TEXT NOT NULL REFERENCES events(id), from_id TEXT NOT NULL REFERENCES users(id), to_id TEXT NOT NULL REFERENCES users(id), fair_play INTEGER NOT NULL CHECK(fair_play BETWEEN 1 AND 5), play_again INTEGER NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(event_id,from_id,to_id));
CREATE TABLE IF NOT EXISTS rating_history (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), event_id TEXT NOT NULL REFERENCES events(id), sport TEXT NOT NULL, delta INTEGER NOT NULL, rating INTEGER NOT NULL, created_at BIGINT NOT NULL, UNIQUE(user_id,event_id));
CREATE TABLE IF NOT EXISTS reliability_history (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), event_id TEXT NOT NULL REFERENCES events(id), delta INTEGER NOT NULL, reason TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(user_id,event_id));
CREATE TABLE IF NOT EXISTS teams (id TEXT PRIMARY KEY, captain_id TEXT NOT NULL REFERENCES users(id), sport TEXT NOT NULL, payload TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS team_members (team_id TEXT NOT NULL REFERENCES teams(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL, status TEXT NOT NULL, PRIMARY KEY(team_id,user_id));
CREATE TABLE IF NOT EXISTS team_invites (id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES teams(id), user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(team_id,user_id));
CREATE TABLE IF NOT EXISTS challenges (id TEXT PRIMARY KEY, from_team TEXT NOT NULL REFERENCES teams(id), to_team TEXT NOT NULL REFERENCES teams(id), created_by TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, event_id TEXT REFERENCES events(id), payload TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS tournaments (id TEXT PRIMARY KEY, creator_id TEXT NOT NULL REFERENCES users(id), sport TEXT NOT NULL, status TEXT NOT NULL, capacity INTEGER NOT NULL, payload TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS tournament_members (tournament_id TEXT NOT NULL REFERENCES tournaments(id), team_id TEXT NOT NULL REFERENCES teams(id), status TEXT NOT NULL, roster TEXT NOT NULL DEFAULT '[]', created_at BIGINT NOT NULL, PRIMARY KEY(tournament_id,team_id));
CREATE TABLE IF NOT EXISTS tournament_fixtures (id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL REFERENCES tournaments(id), round INTEGER NOT NULL, home_team TEXT NOT NULL REFERENCES teams(id), away_team TEXT NOT NULL REFERENCES teams(id), event_id TEXT UNIQUE REFERENCES events(id), UNIQUE(tournament_id,home_team,away_team));
CREATE TABLE IF NOT EXISTS communities (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), access TEXT NOT NULL, payload TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS community_members (community_id TEXT NOT NULL REFERENCES communities(id), user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(community_id,user_id));
CREATE TABLE IF NOT EXISTS venues (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS venue_slots (id TEXT PRIMARY KEY, venue_id TEXT NOT NULL REFERENCES venues(id), starts_at BIGINT NOT NULL, ends_at BIGINT NOT NULL, price_minor INTEGER NOT NULL CHECK(price_minor>=0), status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bookings (id TEXT PRIMARY KEY, slot_id TEXT NOT NULL REFERENCES venue_slots(id), user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, amount_minor INTEGER NOT NULL, split_count INTEGER NOT NULL, cancellation_deadline BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS booking_slot_active ON bookings(slot_id) WHERE status IN ('pending','confirmed');
CREATE TABLE IF NOT EXISTS venue_payments (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, provider_ref TEXT UNIQUE, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS threads (id TEXT PRIMARY KEY, kind TEXT NOT NULL, event_id TEXT UNIQUE REFERENCES events(id), team_id TEXT UNIQUE REFERENCES teams(id), title TEXT NOT NULL, pair_key TEXT UNIQUE, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS thread_members (thread_id TEXT NOT NULL REFERENCES threads(id), user_id TEXT NOT NULL REFERENCES users(id), read_at BIGINT NOT NULL DEFAULT 0, muted INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(thread_id,user_id));
CREATE TABLE IF NOT EXISTS blocks (user_id TEXT NOT NULL REFERENCES users(id), target_id TEXT NOT NULL REFERENCES users(id), created_at BIGINT NOT NULL, PRIMARY KEY(user_id,target_id));
CREATE TABLE IF NOT EXISTS uploads (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), mime TEXT NOT NULL, size INTEGER NOT NULL, object_key TEXT UNIQUE NOT NULL, status TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES threads(id), sender_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, upload_id TEXT REFERENCES uploads(id), created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_thread ON messages(thread_id,created_at,id);
CREATE TABLE IF NOT EXISTS memories (id TEXT PRIMARY KEY, author_id TEXT NOT NULL REFERENCES users(id), upload_id TEXT REFERENCES uploads(id), status TEXT NOT NULL, payload TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS memory_likes (memory_id TEXT NOT NULL REFERENCES memories(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(memory_id,user_id));
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), dedupe TEXT UNIQUE NOT NULL, category TEXT NOT NULL, payload TEXT NOT NULL, read_at BIGINT, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(status,next_at);
CREATE TABLE IF NOT EXISTS push_devices (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), platform TEXT NOT NULL, token TEXT UNIQUE NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS support_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), category TEXT NOT NULL, subject TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), target_type TEXT NOT NULL, target_id TEXT NOT NULL, reason TEXT NOT NULL, details TEXT NOT NULL, status TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS deletion_requests (user_id TEXT PRIMARY KEY REFERENCES users(id), status TEXT NOT NULL, execute_after BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, target_id TEXT NOT NULL, metadata TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS feature_flags (name TEXT PRIMARY KEY, enabled INTEGER NOT NULL, updated_at BIGINT NOT NULL);
INSERT INTO schema_migrations(version,applied_at) VALUES(1,0) ON CONFLICT(version) DO NOTHING;
CREATE TABLE IF NOT EXISTS legal_documents (kind TEXT NOT NULL, version TEXT NOT NULL, url TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, published_at BIGINT NOT NULL, PRIMARY KEY(kind,version));
CREATE TABLE IF NOT EXISTS legal_acceptances (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), terms_version TEXT NOT NULL, privacy_version TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(user_id,terms_version,privacy_version));
CREATE TABLE IF NOT EXISTS discovery_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id), payload TEXT NOT NULL, updated_at BIGINT NOT NULL);
